// Level-progress bar: the FRAME is the `ui_progress_bar` asset (1180×14) and
// the dynamic fill is a rectangle scaled over its inner track. Phase 2 swaps
// the SVG art against the same key/size; the fill logic is untouched.
const barY = 16;
const barW = 1180; // == ui_progress_bar asset width (see assetManifest)
const barLeft = GAME_WIDTH / 2 - barW / 2;
this.progressFill = this.add
  .rectangle(barLeft + 2, barY, barW - 4, 8, 0x6cc04a)
  .setOrigin(0, 0.5);
this.progressFill.scaleX = 0;
this.add.image(GAME_WIDTH / 2, barY, KEYS.ui_progress_bar); // frame over the fill

